class Solution {
    public int longestDecomposition(String text) {
        int n = text.length();
        int leftEnd = 0;
        int rightStart = n - 1;
        int answer = 0;
        StringBuilder left = new StringBuilder();
        StringBuilder right = new StringBuilder();

        while (leftEnd < rightStart) {
            left.append(text.charAt(leftEnd++));
            right.insert(0, text.charAt(rightStart--));
            if (left.toString().equals(right.toString())) {
                answer += 2;
                left.setLength(0);
                right.setLength(0);
            }
        }

        if (leftEnd == rightStart || left.length() > 0) {
            answer++;
        }
        return answer;
    }
}

class Solution {
    private static final long MOD1 = 1_000_000_007L;
    private static final long MOD2 = 1_000_000_009L;
    private static final long BASE = 911_382_323L;

    public int longestDecomposition(String text) {
        int n = text.length();
        int i = 0;
        int j = n - 1;
        int leftStart = 0;
        int count = 0;
        int length = 0;
        long leftHash1 = 0, leftHash2 = 0;
        long rightHash1 = 0, rightHash2 = 0;
        long power1 = 1, power2 = 1;

        while (i < j) {
            int leftValue = text.charAt(i) - 'a' + 1;
            int rightValue = text.charAt(j) - 'a' + 1;
            leftHash1 = (leftHash1 * BASE + leftValue) % MOD1;
            leftHash2 = (leftHash2 * BASE + leftValue) % MOD2;
            rightHash1 = (rightHash1 + rightValue * power1) % MOD1;
            rightHash2 = (rightHash2 + rightValue * power2) % MOD2;
            power1 = power1 * BASE % MOD1;
            power2 = power2 * BASE % MOD2;
            int currentLength = length + 1;

            if (leftHash1 == rightHash1 && leftHash2 == rightHash2
                    && matches(text, leftStart, j, currentLength)) {
                count += 2;
                i++;
                j--;
                leftStart = i;
                length = 0;
                leftHash1 = leftHash2 = rightHash1 = rightHash2 = 0;
                power1 = power2 = 1;
            } else {
                i++;
                j--;
                length = currentLength;
            }
        }

        if (i == j || length > 0) {
            count++;
        }
        return count;
    }

    private boolean matches(String text, int left, int right, int length) {
        for (int offset = 0; offset < length; offset++) {
            if (text.charAt(left + offset) != text.charAt(right + offset)) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    public int longestDecomposition(String text) {
        return solve(text, 0, text.length() - 1);
    }

    private int solve(String text, int left, int right) {
        if (left > right) {
            return 0;
        }

        int maxLength = (right - left + 1) / 2;
        for (int length = 1; length <= maxLength; length++) {
            if (matches(text, left, right - length + 1, length)) {
                return 2 + solve(text, left + length, right - length);
            }
        }
        return 1;
    }

    private boolean matches(String text, int a, int b, int length) {
        for (int i = 0; i < length; i++) {
            if (text.charAt(a + i) != text.charAt(b + i)) {
                return false;
            }
        }
        return true;
    }
}

class Solution {
    private String text;
    private int[][] lcp;
    private int[][] memo;

    public int longestDecomposition(String text) {
        this.text = text;
        int n = text.length();
        lcp = new int[n + 1][n + 1];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (text.charAt(i) == text.charAt(j)) {
                    lcp[i][j] = lcp[i + 1][j + 1] + 1;
                }
            }
        }
        memo = new int[n][n];
        return dp(0, n - 1);
    }

    private int dp(int left, int right) {
        if (left > right) {
            return 0;
        }
        if (memo[left][right] != 0) {
            return memo[left][right];
        }

        int best = 1;
        int maxLength = (right - left + 1) / 2;
        for (int length = 1; length <= maxLength; length++) {
            int suffixStart = right - length + 1;
            if (lcp[left][suffixStart] >= length) {
                best = Math.max(best, 2 + dp(left + length, right - length));
            }
        }
        memo[left][right] = best;
        return best;
    }
}

class Solution {
    public int longestDecomposition(String text) {
        int answer = 0;
        int left = 0;
        int right = text.length() - 1;
        while (left <= right) {
            String segment = text.substring(left, right + 1);
            int border = shortestLegalBorder(segment);
            if (border == 0) {
                return answer + 1;
            }
            answer += 2;
            left += border;
            right -= border;
        }
        return answer;
    }

    private int shortestLegalBorder(String segment) {
        int[] pi = prefixFunction(segment);
        int best = 0;
        for (int length = pi[segment.length() - 1]; length > 0; length = pi[length - 1]) {
            if (length * 2 <= segment.length()) {
                best = length;
            }
        }
        return best;
    }

    private int[] prefixFunction(String s) {
        int[] pi = new int[s.length()];
        for (int i = 1; i < s.length(); i++) {
            int j = pi[i - 1];
            while (j > 0 && s.charAt(i) != s.charAt(j)) {
                j = pi[j - 1];
            }
            if (s.charAt(i) == s.charAt(j)) {
                j++;
            }
            pi[i] = j;
        }
        return pi;
    }
}
